<script setup lang="ts">
import { ref } from 'vue';
import type { Row } from '../../shared/domain';
import { railwayPlaces, railwayQuestions, railwaySources, railwayDate, safeRailwayUrl, useRailway } from '../../shared/railway';
const props = defineProps<{ notices: Row[]; manage?: boolean }>();
const emit = defineEmits<{ (event: 'publish', category: string): void; (event: 'edit', row: Row): void }>();
const { section, place, expanded, question, articles, filtered, chooseSection } = useRailway(() => props.notices);
const message = ref('');
const root = ref<HTMLElement | null>(null);
function showNews(value = '全部') { chooseSection(value);root.value?.querySelector('#rail-news')?.scrollIntoView({ behavior: window.matchMedia('(prefers-reduced-motion: reduce)').matches ? 'auto' : 'smooth' }); }
async function share() {
  try { await navigator.clipboard.writeText(location.origin + location.pathname + '#railway');message.value = '专题链接已复制，可以分享给老乡。'; }
  catch { message.value = '暂时无法复制，请复制浏览器地址栏中的专题链接。'; }
}
</script>
<template>
  <div ref="root" class="railway-hub">
    <header class="rail-page-heading"><div><div class="rail-kicker">家乡新连接 · 淮新高铁专题</div><h1 class="rail-page-title">一凡说高铁 <span class="hot-badge">HOT</span></h1><p class="rail-lead">关心一条路，也关心每一次回家。</p></div><button class="rail-button rail-outline" @click="share">分享专题 ↗</button></header>
    <p v-if="message" class="rail-feedback" role="status">{{ message }}</p>
    <section class="rail-hero"><div class="rail-hero-copy"><span class="rail-hero-label">和老乡一起，关注家乡高铁</span><h2 class="rail-hero-title">回家的期待，<br><span>在这里相遇。</span></h2><p class="rail-hero-text">从规划消息到出行关注，<br>一起读懂淮新高铁，记录家乡的新连接。</p><div class="rail-hero-actions"><a class="rail-button rail-gold" href="#rail-news" @click.prevent="showNews()">查看专题动态 ↓</a><span class="rail-hero-note">资讯有出处 · 观点有标注</span></div></div><img class="rail-art" src="/brand/railway-scene.svg" alt="列车与家乡风景的主题插画"></section>
    <div class="rail-layout">
      <section class="rail-card rail-route"><div class="rail-section-head"><div><span class="rail-kicker">沿着家乡，了解更多</span><h2 class="rail-section-title">三个区域，一份牵挂</h2></div><span class="rail-mini-label">区域示意</span></div><div class="rail-route-line" role="group" aria-label="选择关注区域"><button v-for="(item, i) in railwayPlaces" :key="item.name" :class="['rail-place',{active:place===i}]" :aria-pressed="place===i" @click="place=i"><span class="rail-point"></span><strong>{{ item.name }}</strong><span>{{ item.label }}</span></button></div><div class="rail-place-detail" aria-live="polite"><strong>{{ railwayPlaces[place].name }} · {{ railwayPlaces[place].label }}</strong><p>{{ railwayPlaces[place].text }}</p></div><p class="rail-caption">区域关系示意，非正式站点及施工线路图。</p></section>
      <aside class="rail-editorial"><div class="rail-editorial-mark">凡</div><span class="rail-kicker">一个老乡的高铁观察</span><h2 class="rail-section-title">消息与期待，慢慢聊。</h2><p>把大家关心的问题讲明白，<br>把信息的来龙去脉说清楚。</p><button class="rail-button rail-outline" @click="showNews('一凡说高铁')">看看一凡的解读 →</button><span class="rail-caption">个人观察与解读，单独标注。</span></aside>
    </div>
    <section id="rail-news" class="rail-news"><div class="rail-section-head"><div><span class="rail-kicker">消息有来处，关注有方向</span><h2 class="rail-section-title">专题动态 <span class="rail-total">{{ articles.length }}</span></h2></div><button v-if="manage" class="rail-button rail-primary" @click="emit('publish', section==='一凡说高铁' ? section : '淮新高铁')">＋ 发布内容</button></div><div class="rail-tabs" role="group" aria-label="专题内容筛选"><button v-for="item in ['全部','淮新高铁','一凡说高铁']" :key="item" :class="{active:section===item}" :aria-pressed="section===item" @click="chooseSection(item)">{{ item==='淮新高铁' ? '专题资讯' : item==='一凡说高铁' ? '一凡解读' : item }}</button></div><div v-if="!filtered.length" class="rail-empty"><span class="rail-empty-symbol">↗</span><h3>{{ section==='一凡说高铁' ? '一凡的高铁观察，正在整理中' : '把值得关注的消息，留在这里' }}</h3><p>{{ section==='一凡说高铁' ? '解读发布后，会在这个栏目与你见面。' : '专题内容发布后将在这里展示，你也可以先查看下方的官方信息入口。' }}</p></div><article v-for="item in filtered" :key="item.id" class="rail-article"><div class="rail-article-meta"><span :class="['rail-category',{opinion:item.category==='一凡说高铁'}]">{{ item.category==='一凡说高铁' ? '一凡解读 · 观点' : '专题资讯' }}</span><time>{{ railwayDate(item.sourceDate || item.createdAt) }}</time></div><h3 class="rail-article-title"><button :aria-expanded="expanded===item.id" @click="expanded=expanded===item.id ? '' : item.id">{{ item.title }}</button></h3><p :class="['rail-article-copy',{collapsed:expanded!==item.id}]">{{ item.content }}</p><div class="rail-article-bottom"><span>来源：{{ item.sourceName || (item.category==='一凡说高铁' ? '一凡说高铁' : '平台整理') }}</span><div><a v-if="safeRailwayUrl(item.sourceUrl)" class="rail-text-button" :href="safeRailwayUrl(item.sourceUrl)" target="_blank" rel="noopener noreferrer">查看原文 ↗</a><button class="rail-text-button" :aria-expanded="expanded===item.id" @click="expanded=expanded===item.id ? '' : item.id">{{ expanded===item.id ? '收起' : '阅读全文' }}</button><button v-if="manage" class="rail-text-button" @click="emit('edit',item)">编辑</button></div></div></article></section>
    <div class="rail-layout rail-bottom"><section class="rail-card"><div class="rail-section-head"><h2 class="rail-section-title">老乡关心的问题</h2></div><div v-for="(item,i) in railwayQuestions" :key="item.question" class="rail-faq"><button :aria-expanded="question===i" :aria-controls="'rail-answer-'+i" @click="question=question===i ? -1 : i"><span>{{ item.question }}</span><span aria-hidden="true">{{ question===i ? '−' : '＋' }}</span></button><p v-if="question===i" :id="'rail-answer-'+i">{{ item.answer }}</p></div></section><aside class="rail-card"><div class="rail-section-head"><h2 class="rail-section-title">官方信息入口</h2></div><a v-for="item in railwaySources" :key="item.url" class="rail-source" :href="item.url" target="_blank" rel="noopener noreferrer"><span><strong>{{ item.title }}</strong><span>{{ item.description }}</span></span><span aria-hidden="true">↗</span></a><p class="rail-caption">站点、开工与通车时间，以正式批复及运营公告为准。</p></aside></div>
  </div>
</template>
<style scoped src="../../shared/railway.css"></style>
